contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // single public test function taking the ticket amount as parameter and sending that much Ether
    function run(uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(address(this).balance >= amount);
        // observe before-values
        address bankBefore = c.bank(); if (__ESBMC_reverted()) return;
        uint potBefore = c.pot(); if (__ESBMC_reverted()) return;
        uint balBefore = address(c).balance;

        bool reverted;
        // make the call that may change state; send amount from this contract
        c.play{value: amount}(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // observe after-values
        address bankAfter = c.bank(); if (__ESBMC_reverted()) return;
        uint potAfter = c.pot(); if (__ESBMC_reverted()) return;
        uint balAfter = address(c).balance;

        // General invariant:
        // - bank address must never change
        // - if call reverted, pot and balance unchanged
        // - if call succeeded, potAfter is either 0 or potBefore + amount
        // (This encodes that a successful play either triggers a payout clearing pot or accumulates the ticket.)
        assert(
            bankBefore == bankAfter
            && (reverted
                ? (potAfter == potBefore && balAfter == balBefore)
                : (potAfter == 0 || potAfter == potBefore + amount))
        );
    }

    // receive to accept refunds/payments from c when it transfers
    receive() external payable { }
}

